#!/usr/bin/env python3
# SPDX-License-Identifier: MIT
"""Build authored M6 Office OPC decks with only the Python standard library.

Run with --check to reconstruct and compare every generated byte. Downloaded
originals are never rewritten. Geometry is in points; no reference colors or
sample coordinates are stored in the decks or manifests.
"""
import argparse
from io import BytesIO
import hashlib
import json
from pathlib import Path
import struct
import xml.etree.ElementTree as ET
from zipfile import ZIP_STORED, ZipFile, ZipInfo
import zlib

HERE = Path(__file__).resolve().parent
PALETTE = ('245A81', 'D97B28', '4C8250', '805BA3', '269CA8', 'D1A52B')
NS = dict(p='http://schemas.openxmlformats.org/presentationml/2006/main',
          a='http://schemas.openxmlformats.org/drawingml/2006/main',
          r='http://schemas.openxmlformats.org/officeDocument/2006/relationships')
REL = 'http://schemas.openxmlformats.org/package/2006/relationships'
for prefix, uri in NS.items():
    ET.register_namespace(prefix, uri)


def qn(tag):
    prefix, name = tag.split(':')
    return '{' + NS[prefix] + '}' + name


def xml(tag, **attrs):
    return ET.Element(qn(tag), {key: str(value) for key, value in attrs.items()})


def add(parent, tag, **attrs):
    child = xml(tag, **attrs)
    parent.append(child)
    return child


def emu(value):
    return round(value * 12700)


class Shapes:
    def __init__(self, page, parent):
        self.page, self.parent = page, parent

    def append(self, tag, kind):
        self.page.number += 1
        number = self.page.number
        shape = add(self.parent, 'p:' + tag)
        nvtag = {'sp': 'nvSpPr', 'pic': 'nvPicPr', 'grpSp': 'nvGrpSpPr',
                 'cxnSp': 'nvCxnSpPr', 'graphicFrame': 'nvGraphicFramePr'}[tag]
        props = add(shape, 'p:' + nvtag)
        add(props, 'p:cNvPr', id=number, name=f'{kind} {number - 1}')
        add(props, 'p:' + {'sp': 'cNvSpPr', 'pic': 'cNvPicPr', 'grpSp': 'cNvGrpSpPr',
                          'cxnSp': 'cNvCxnSpPr', 'graphicFrame': 'cNvGraphicFramePr'}[tag])
        add(props, 'p:nvPr')
        return shape


class Deck:
    def __init__(self, wide):
        self.width, self.height, self.slides = 960 if wide else 720, 540, []


class Page:
    def __init__(self):
        self.number, self.has_image = 1, False
        self.root = xml('p:sld')
        self.content = add(self.root, 'p:cSld')
        tree = add(self.content, 'p:spTree')
        nv = add(tree, 'p:nvGrpSpPr')
        add(nv, 'p:cNvPr', id=1, name='')
        add(nv, 'p:cNvGrpSpPr')
        add(nv, 'p:nvPr')
        add(tree, 'p:grpSpPr')
        self.shapes = Shapes(self, tree)
        add(add(self.root, 'p:clrMapOvr'), 'a:masterClrMapping')


def presentation(wide=True):
    return Deck(wide)


def slide(deck):
    page = Page()
    deck.slides.append(page)
    return page


def transform(props, box, tag='a:xfrm', **attrs):
    x, y, w, h = (emu(value) for value in box)
    xf = add(props, tag, **attrs)
    add(xf, 'a:off', x=x, y=y)
    add(xf, 'a:ext', cx=w, cy=h)
    return xf


def fill(color, alpha=None, scheme=False):
    node = xml('a:solidFill')
    value = add(node, 'a:schemeClr' if scheme else 'a:srgbClr', val=color)
    if alpha is not None:
        add(value, 'a:alpha', val=alpha)
    return node


def paragraph(value, size=24, color='172D3E', bold=False, level=None):
    node = xml('a:p')
    attrs = {} if level is None else dict(lvl=level, marL=emu((level + 1) * 30), indent=emu(-22))
    props = add(node, 'a:pPr', **attrs)
    add(add(props, 'a:spcBef'), 'a:spcPts', val=0)
    add(add(props, 'a:spcAft'), 'a:spcPts', val=1200)
    if level is not None:
        add(props, 'a:buChar', char='•')
    run = add(node, 'a:r')
    props = add(run, 'a:rPr', sz=round(size * 100), b=int(bold))
    props.append(fill(color))
    add(props, 'a:latin', typeface='Arial')
    add(run, 'a:t').text = value
    return node


def text(shapes, value, box, size=24, color='172D3E', bold=False, levels=None):
    shape = shapes.append('sp', 'TextBox')
    shape.find('.//' + qn('p:cNvSpPr')).set('txBox', '1')
    props = add(shape, 'p:spPr')
    transform(props, box)
    add(add(props, 'a:prstGeom', prst='rect'), 'a:avLst')
    add(props, 'a:noFill')
    body = add(shape, 'p:txBody')
    add(add(body, 'a:bodyPr', wrap='square', lIns=0, rIns=0, tIns=0, bIns=0, anchor='t'), 'a:spAutoFit')
    add(body, 'a:lstStyle')
    for i, line in enumerate(value.split('\n')):
        body.append(paragraph(line, size, color, bold, levels[i] if levels else None))
    return shape


def title(page, value, width=864):
    return text(page.shapes, value, (48, 28, width, 66), 32, bold=True)


def solid(shapes, geometry, box, color, alpha=None, scheme=False):
    names = dict(rect='Rectangle', roundRect='Rounded Rectangle', ellipse='Oval', triangle='Isosceles Triangle')
    shape = shapes.append('sp', names[geometry])
    props = add(shape, 'p:spPr')
    transform(props, box)
    add(add(props, 'a:prstGeom', prst=geometry), 'a:avLst')
    props.append(fill(color, alpha, scheme))
    add(add(props, 'a:ln'), 'a:noFill')
    return shape


def png(width, height, pixel):
    def chunk(tag, data):
        return struct.pack('>I', len(data)) + tag + data + struct.pack('>I', zlib.crc32(tag + data))
    raw = b''.join(b'\0' + b''.join(bytes(pixel(x, y)) for x in range(width)) for y in range(height))
    # Explicit stored DEFLATE blocks avoid zlib/zlib-ng block-boundary differences.
    stored = bytearray(b'\x78\x01')
    for start in range(0, len(raw), 65535):
        block = raw[start:start + 65535]
        stored += struct.pack('<BHH', int(start + len(block) == len(raw)), len(block), len(block) ^ 0xffff) + block
    stored += struct.pack('>I', zlib.adler32(raw))
    return (b'\x89PNG\r\n\x1a\n' + chunk(b'IHDR', struct.pack('>IIBBBBB', width, height, 8, 2, 0, 0, 0)) +
            chunk(b'IDAT', stored) + chunk(b'IEND', b''))


def illustration():
    """Original landscape, rasterized by integer geometry into a stored PNG."""
    def polygon(x, y, points):
        inside = False
        for (ax, ay), (bx, by) in zip(points, points[1:] + points[:1]):
            if (ay > y) != (by > y) and x < (bx - ax) * (y - ay) / (by - ay) + ax:
                inside = not inside
        return inside
    def pixel(x, y):
        if y >= 135:
            return (105, 149, 79)
        if polygon(x, y, ((64, 160), (164, 66), (240, 141), (240, 160))):
            return (49, 88, 109)
        if polygon(x, y, ((0, 126), (65, 52), (132, 126))):
            return (70, 115, 136)
        if (x - 187) ** 2 + (y - 41) ** 2 <= 21 ** 2:
            return (241, 204, 83)
        return (144, 197, 223)
    return png(240, 160, pixel)


def image_fill(tag='p:blipFill', tile=False):
    node = xml(tag)
    add(node, 'a:blip').set(qn('r:embed'), 'image')
    if tile:
        add(node, 'a:tile', tx=0, ty=0, sx=100000, sy=100000, flip='none', algn='tl')
    else:
        add(add(node, 'a:stretch'), 'a:fillRect')
    return node


def picture(shapes, box=(48, 142, 360, 240), tile=False, flipH=False, flipV=False, rotation=0):
    shapes.page.has_image = True
    shape = shapes.append('pic', 'Picture')
    shape.append(image_fill(tile=tile))
    props = add(shape, 'p:spPr')
    transform(props, box, **dict(([('flipH', '1')] if flipH else []) +
                               ([('flipV', '1')] if flipV else []) +
                               ([('rot', rotation * 60000)] if rotation else [])))
    add(add(props, 'a:prstGeom', prst='rect'), 'a:avLst')
    return shape


def picture_fill(page, box=(48, 142, 360, 240)):
    page.has_image = True
    shape = solid(page.shapes, 'roundRect', box, 'FFFFFF')
    props = shape.find(qn('p:spPr'))
    props.remove(props.find(qn('a:solidFill')))
    props.insert(2, image_fill('a:blipFill'))
    return shape


def connector(shapes, start=(576, 356), end=(848, 356)):
    shape = shapes.append('cxnSp', 'Connector')
    props = add(shape, 'p:spPr')
    transform(props, (*start, end[0] - start[0], end[1] - start[1]))
    add(add(props, 'a:prstGeom', prst='line'), 'a:avLst')
    add(props, 'a:ln', w=emu(3)).append(fill('FFFFFF'))
    return shape


def table(shapes, box=(48, 132, 864, 300), chinese=False, merged=False):
    shape = shapes.append('graphicFrame', 'Table')
    transform(shape, box, 'p:xfrm')
    grid = add(add(add(shape, 'a:graphic'), 'a:graphicData', uri='http://schemas.openxmlformats.org/drawingml/2006/table'), 'a:tbl')
    add(grid, 'a:tblPr')
    columns = add(grid, 'a:tblGrid')
    for _ in range(3):
        add(columns, 'a:gridCol', w=emu(box[2] / 3))
    labels = (('区域', '项目', '状态'), ('北部', '采样', '完成'), ('南部', '分析', '进行中')) if chinese else (
        ('Team', 'Workstream', 'Status'), ('North', 'Collection', 'Complete'), ('South', 'Analysis', 'Active'))
    for r in range(3):
        row = add(grid, 'a:tr', h=emu(box[3] / 3))
        for c in range(3):
            attrs, values = {}, [labels[r][c]]
            if merged and (r, c) == (0, 0): attrs, values = dict(gridSpan=2), ['Delivery programme']
            if merged and (r, c) == (0, 1): attrs, values = dict(hMerge=1), []
            if merged and (r, c) == (1, 0): attrs, values = dict(rowSpan=2), ['Regional teams', 'South']
            if merged and (r, c) == (2, 0): attrs, values = dict(vMerge=1), []
            cell = add(row, 'a:tc', **attrs)
            body = add(cell, 'a:txBody')
            add(body, 'a:bodyPr')
            add(body, 'a:lstStyle')
            for value in values: body.append(paragraph(value, 22, bold=r == 0))
            if not values: add(body, 'a:p')
            props = add(cell, 'a:tcPr', marL=emu(12), marR=emu(12), marT=emu(10), marB=emu(10), anchor='ctr')
            for side in ('L', 'R', 'T', 'B'):
                add(props, 'a:ln' + side, w=12700).append(fill('48718A'))
            props.append(fill(('DAE7EF', 'EEF4F7', 'E4EEE3')[r]))
    return grid


def group(shapes):
    outer = shapes.append('grpSp', 'Group')
    xf = transform(add(outer, 'p:grpSpPr'), (90, 160, 716.8, 187))
    add(xf, 'a:chOff', x=emu(90), y=emu(160))
    add(xf, 'a:chExt', cx=emu(640), cy=emu(170))
    children = Shapes(shapes.page, outer)
    solid(children, 'roundRect', (90, 160, 270, 170), 'DAE7EF')
    text(children, 'Planning', (112, 183, 220, 48), 26, bold=True)
    inner = children.append('grpSp', 'Group')
    xf = transform(add(inner, 'p:grpSpPr'), (405, 160, 325, 150))
    add(xf, 'a:chOff', x=emu(405), y=emu(160))
    add(xf, 'a:chExt', cx=emu(325), cy=emu(150))
    nested = Shapes(shapes.page, inner)
    solid(nested, 'ellipse', (405, 160, 140, 140), '4C8250')
    solid(nested, 'triangle', (580, 180, 150, 130), 'D97B28')
    return outer


def gradient(left, right):
    node = xml('a:gradFill', rotWithShape=1)
    stops = add(node, 'a:gsLst')
    for pos, color in ((0, left), (100000, right)):
        add(add(stops, 'a:gs', pos=pos), 'a:srgbClr', val=color)
    add(node, 'a:lin', ang=0, scaled=0)
    return node


def archive(parts):
    out = BytesIO()
    with ZipFile(out, 'w') as target:
        for name, data in sorted(parts.items()):
            item = ZipInfo(name, (2020, 1, 1, 0, 0, 0))
            item.compress_type, item.create_system, item.external_attr = ZIP_STORED, 3, 0o600 << 16
            target.writestr(item, data)
    return out.getvalue()


def relationships(items):
    return f'<Relationships xmlns="{REL}">' + ''.join(
        f'<Relationship Id="{key}" Type="{NS["r"]}/{kind}" Target="{target}"/>' for key, kind, target in items) + '</Relationships>'


def package(deck):
    """Author all OPC parts from source data, without an installed Office library."""
    empty_tree = '<p:spTree><p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr><p:grpSpPr/></p:spTree>'
    declarations = ' '.join(f'xmlns:{key}="{value}"' for key, value in NS.items())
    mapping = ' '.join(f'{key}="{value}"' for key, value in dict(bg1='lt1', tx1='dk1', bg2='lt2', tx2='dk2', **{f'accent{i}':f'accent{i}' for i in range(1, 7)}, hlink='hlink', folHlink='folHlink').items())
    colors = dict(dk1='000000', lt1='FFFFFF', dk2='1F497D', lt2='EEECE1', accent1='4F81BD', accent2='C0504D', accent3='9BBB59', accent4='8064A2', accent5='4BACC6', accent6='F79646', hlink='0000FF', folHlink='800080')
    scheme = ''.join(f'<a:{key}><a:srgbClr val="{value}"/></a:{key}>' for key, value in colors.items())
    theme_fill = '<a:solidFill><a:schemeClr val="phClr"/></a:solidFill>'
    fonts = ''.join(f'<a:{kind}Font><a:latin typeface="Calibri"/><a:ea typeface=""/><a:cs typeface=""/></a:{kind}Font>' for kind in ('major', 'minor'))
    parts = {
        '_rels/.rels': relationships([('office', 'officeDocument', 'ppt/presentation.xml')]).replace('</Relationships>', '<Relationship Id="core" Type="http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties" Target="docProps/core.xml"/><Relationship Id="app" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/extended-properties" Target="docProps/app.xml"/></Relationships>'),
        'docProps/core.xml': '<cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:dcterms="http://purl.org/dc/terms/" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"><dc:title>EXReader M6 authored presentation corpus</dc:title><dc:creator>EXReader contributors</dc:creator><dc:subject>MIT licensed authored compatibility corpus</dc:subject><cp:lastModifiedBy>EXReader contributors</cp:lastModifiedBy><cp:revision>1</cp:revision><dcterms:created xsi:type="dcterms:W3CDTF">2020-01-01T00:00:00Z</dcterms:created><dcterms:modified xsi:type="dcterms:W3CDTF">2020-01-01T00:00:00Z</dcterms:modified></cp:coreProperties>',
        'docProps/app.xml': f'<Properties xmlns="http://schemas.openxmlformats.org/officeDocument/2006/extended-properties"><Application>EXReader stdlib fixture generator</Application><Slides>{len(deck.slides)}</Slides></Properties>',
        'ppt/presentation.xml': f'<p:presentation {declarations}><p:sldMasterIdLst><p:sldMasterId id="2147483648" r:id="master"/></p:sldMasterIdLst><p:sldIdLst>' + ''.join(f'<p:sldId id="{255+i}" r:id="slide{i}"/>' for i in range(1, len(deck.slides)+1)) + f'</p:sldIdLst><p:sldSz cx="{emu(deck.width)}" cy="{emu(deck.height)}"/><p:notesSz cx="6858000" cy="9144000"/></p:presentation>',
        'ppt/_rels/presentation.xml.rels': relationships([('master', 'slideMaster', 'slideMasters/slideMaster1.xml')] + [(f'slide{i}', 'slide', f'slides/slide{i}.xml') for i in range(1, len(deck.slides)+1)]),
        'ppt/slideMasters/slideMaster1.xml': f'<p:sldMaster {declarations}><p:cSld>{empty_tree}</p:cSld><p:clrMap {mapping}/><p:sldLayoutIdLst><p:sldLayoutId id="2147483649" r:id="layout"/></p:sldLayoutIdLst><p:txStyles><p:titleStyle/><p:bodyStyle/><p:otherStyle/></p:txStyles></p:sldMaster>',
        'ppt/slideMasters/_rels/slideMaster1.xml.rels': relationships([('layout', 'slideLayout', '../slideLayouts/slideLayout1.xml'), ('theme', 'theme', '../theme/theme1.xml')]),
        'ppt/slideLayouts/slideLayout1.xml': f'<p:sldLayout {declarations} type="blank" preserve="1"><p:cSld name="Blank">{empty_tree}</p:cSld><p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:sldLayout>',
        'ppt/slideLayouts/_rels/slideLayout1.xml.rels': relationships([('master', 'slideMaster', '../slideMasters/slideMaster1.xml')]),
        'ppt/theme/theme1.xml': f'<a:theme xmlns:a="{NS["a"]}" name="Office"><a:themeElements><a:clrScheme name="Office">{scheme}</a:clrScheme><a:fontScheme name="Office">{fonts}</a:fontScheme><a:fmtScheme name="Office"><a:fillStyleLst>{theme_fill * 3}</a:fillStyleLst><a:lnStyleLst>' + ('<a:ln w="12700">' + theme_fill + '</a:ln>') * 3 + f'</a:lnStyleLst><a:effectStyleLst>{"<a:effectStyle><a:effectLst/></a:effectStyle>" * 3}</a:effectStyleLst><a:bgFillStyleLst>{theme_fill * 3}</a:bgFillStyleLst></a:fmtScheme></a:themeElements></a:theme>',
    }
    types = {'/ppt/presentation.xml': 'presentationml.presentation.main', '/ppt/slideMasters/slideMaster1.xml': 'presentationml.slideMaster', '/ppt/slideLayouts/slideLayout1.xml': 'presentationml.slideLayout', '/ppt/theme/theme1.xml': 'theme', '/docProps/core.xml': 'package.core-properties', '/docProps/app.xml': 'extended-properties'}
    for i, page in enumerate(deck.slides, 1):
        parts[f'ppt/slides/slide{i}.xml'] = ET.tostring(page.root, encoding='utf-8', xml_declaration=True)
        rels = [('layout', 'slideLayout', '../slideLayouts/slideLayout1.xml')]
        if page.has_image: rels.append(('image', 'image', '../media/image1.png'))
        parts[f'ppt/slides/_rels/slide{i}.xml.rels'] = relationships(rels)
        types[f'/ppt/slides/slide{i}.xml'] = 'presentationml.slide'
    if any(page.has_image for page in deck.slides):
        parts['ppt/media/image1.png'] = illustration()
    parts['[Content_Types].xml'] = '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Default Extension="png" ContentType="image/png"/>' + ''.join(f'<Override PartName="{name}" ContentType="application/vnd.openxmlformats-officedocument.{kind}+xml"/>' if kind != 'package.core-properties' else f'<Override PartName="{name}" ContentType="application/vnd.openxmlformats-package.core-properties+xml"/>' for name, kind in types.items()) + '</Types>'
    return archive(parts)


def cases():
    items = {}

    deck = presentation()
    text(slide(deck).shapes, 'A practical roadmap', (96, 190, 768, 100), 44, bold=True)
    items['title'] = (deck, ['text', 'title', '16:9'])

    deck = presentation()
    page = slide(deck)
    title(page, 'From fieldwork to findings')
    text(page.shapes, 'Collect source material\nInterview the team\nRecord open questions\nCompare the evidence\nPublish the conclusions',
         (72, 135, 816, 300), 26, levels=[0, 1, 2, 0, 1])
    items['bullets'] = (deck, ['text', 'bullets', 'levels-0-1-2', '16:9'])

    deck = presentation()
    page = slide(deck)
    title(page, 'A landscape in context')
    picture(page.shapes)
    text(page.shapes, 'Observation notes\nThe valley connects two survey areas.\nCompare the ridge and the lowlands.',
         (468, 140, 432, 260), 25)
    items['image-text'] = (deck, ['text', 'png', 'image-stretch', '16:9'])

    deck = presentation()
    page = slide(deck)
    title(page, 'Programme delivery')
    table(page.shapes, merged=True)
    items['merged-table'] = (deck, ['text', 'table', 'gridSpan', 'rowSpan', 'hMerge', 'vMerge', 'cell-borders', '16:9'])

    deck = presentation()
    page = slide(deck)
    background = xml('p:bg')
    add(background, 'p:bgPr').append(gradient('DBEBF5', '5792B7'))
    page.content.insert(0, background)
    title(page, 'Layers of the atmosphere')
    solid(page.shapes, 'rect', (72, 148, 430, 232), 'D97B28', 55000)
    solid(page.shapes, 'ellipse', (338, 182, 245, 245), '245A81', 65000)
    solid(page.shapes, 'roundRect', (620, 150, 260, 245), '4C8250', 45000)
    swatch = solid(page.shapes, 'rect', (72, 403, 510, 22), '245A81')
    props = swatch.find(qn('p:spPr'))
    props.remove(props.find(qn('a:solidFill')))
    props.insert(2, gradient('245A81', '269CA8'))
    text(page.shapes, 'Translucent regions show overlapping observations.', (72, 452, 816, 54), 23)
    items['gradient-alpha'] = (deck, ['text', 'gradient-background', 'alpha', 'rect', 'ellipse', 'roundRect', '16:9'])

    deck = presentation()
    page = slide(deck)
    title(page, 'Six themes for a shared programme')
    for i in range(6):
        shape = solid(page.shapes, 'roundRect',
                      (48 + i % 3 * 294, 130 + i // 3 * 168, 270, 140), 'accent' + str(i + 1), scheme=True)
        text(page.shapes, 'Theme ' + str(i + 1), (66 + i % 3 * 294, 170 + i // 3 * 168, 232, 48), 25, 'FFFFFF', True)
    items['theme-accents'] = (deck, ['text', 'schemeClr', 'accent1', 'accent2', 'accent3', 'accent4', 'accent5', 'accent6', '16:9'])

    deck = presentation()
    page = slide(deck)
    title(page, '研究进展与下一步计划')
    text(page.shapes, '数据采集已经完成，团队正在整理分析结果。', (48, 112, 864, 62), 26)
    table(page.shapes, (48, 210, 864, 270), chinese=True)
    items['chinese'] = (deck, ['text', 'cjk-title', 'cjk-body', 'cjk-table', 'table', '16:9'])

    for wide, name in ((False, 'standard-4x3'), (True, 'wide-16x9')):
        deck = presentation(wide)
        page = slide(deck)
        width = 960 if wide else 720
        title(page, 'Space for ideas', width - 96)
        text(page.shapes, 'Review • discuss • decide', (48, 120, width - 96, 50), 26)
        solid(page.shapes, 'rect', (48, 220, (width - 128) / 2, 214), PALETTE[0])
        solid(page.shapes, 'ellipse', (width / 2 + 16, 220, (width - 128) / 2, 214), PALETTE[1])
        items[name] = (deck, ['text', 'rect', 'ellipse', '16:9' if wide else '4:3'])

    deck = presentation()
    page = slide(deck)
    title(page, 'A programme has connected parts')
    group(page.shapes)
    text(page.shapes, 'Nested groups retain their own coordinate systems.', (90, 430, 780, 52), 24)
    items['nested-groups'] = (deck, ['text', 'grpSp', 'nested-grpSp', 'group-scale', 'roundRect', 'ellipse', 'triangle', '16:9'])

    deck = presentation()
    for i in range(20):
        page = slide(deck)
        title(page, f'Programme review — stage {i + 1:02d}')
        if i % 4 == 0:
            text(page.shapes, 'Progress this week\nEvidence collected\nAnalysis in progress', (48, 140, 432, 250), 27)
            solid(page.shapes, 'roundRect', (540, 140, 360, 265), PALETTE[i % 6])
            solid(page.shapes, 'ellipse', (576, 195, 84, 84), 'DAE7EF')
            solid(page.shapes, 'triangle', (740, 195, 84, 84), 'DAE7EF')
            connector(page.shapes)
        elif i % 4 == 1:
            if i == 9:
                picture_fill(page)
            else:
                picture(page.shapes, (98, 152, 300, 200) if i == 17 else (48, 142, 360, 240),
                        tile=i == 5, flipH=i == 13, flipV=i == 17, rotation=90 if i == 17 else 0)
            text(page.shapes, 'Field observations\nCompare successive records.\nShare the next actions.', (468, 145, 432, 270), 26)
        elif i % 4 == 2:
            table(page.shapes)
        else:
            group(page.shapes)
        text(page.shapes, f'Review record {i + 1} / 20', (48, 476, 864, 36), 16)
    items['twenty'] = (deck, ['text', 'png', 'image-stretch', 'image-tile', 'shape-picture-fill',
                             'flipH', 'flipV', 'quarter-rotation', 'line', 'ellipse', 'circle',
                             'triangle', 'table', 'grpSp', 'nested-grpSp', '20-slides', '16:9'])
    return items


def generate(check=False):
    payloads = {}
    for name, (deck, features) in cases().items():
        payloads[name] = package(deck)
        manifest = dict(file=name + '.pptx', slides=len(deck.slides), features=features,
                        source='generated', license='MIT')
        if name == 'twenty':
            manifest['benchmark'] = True
        save_case(name, payloads[name], manifest, check)

    valid = payloads['title']
    with ZipFile(BytesIO(valid)) as source:
        parts = {name: source.read(name) for name in source.namelist()}
    damaged = {
        'bad-truncated': valid[:len(valid) // 2],
        'bad-missing-part': archive({k: v for k, v in parts.items() if k != 'ppt/presentation.xml'}),
        'bad-invalid-xml': archive(dict(parts, **{'ppt/slides/slide1.xml': b'<p:sld xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main"><p:cSld></p:sld>'})),
    }
    for name, data in damaged.items():
        save_case(name, data, dict(file=name + '.pptx', slides=0, features=[name[4:]],
                                 source='generated', license='MIT', expected_status=5,
                                 expected_error='EXR_FORMAT'), check)
    summary_manifest(check)


def summary_manifest(check):
    """Index local manifests, retaining downloaded provenance without rewriting it."""
    entries = []
    for path in sorted(HERE.glob('*/manifest.json')):
        entry = json.loads(path.read_text(encoding='utf-8'))
        entry['file'] = (path.parent / entry['file']).relative_to(HERE).as_posix()
        entries.append(entry)
    content = json.dumps(entries, ensure_ascii=False, indent=2) + '\n'
    target = HERE / 'manifest.json'
    if check:
        assert target.read_text(encoding='utf-8') == content, 'summary manifest differs from child manifests'
    else:
        target.write_text(content, encoding='utf-8', newline='\n')
    print(f'manifest.json: {len(entries)} files, {sum(e["slides"] for e in entries)} valid slides')


def save_case(name, data, manifest, check):
    folder = HERE / name
    manifest.update(sha256=hashlib.sha256(data).hexdigest(), bytes=len(data))
    content = json.dumps(manifest, ensure_ascii=False, indent=2) + '\n'
    if check:
        assert (folder / manifest['file']).read_bytes() == data, name
        assert (folder / 'manifest.json').read_text(encoding='utf-8') == content, name
    else:
        folder.mkdir(parents=True, exist_ok=True)
        (folder / manifest['file']).write_bytes(data)
        (folder / 'manifest.json').write_text(content, encoding='utf-8', newline='\n')
    print(f'{name}: slides={manifest["slides"]} source={manifest["source"]} ZIP_STORED bytes={len(data)}')


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    generate(parser.parse_args().check)
